// Starts and joins std::thread without the project allocator, to tell a toolchain problem from an allocator problem.
#include <cstdio>
#include <thread>
int main()
{
	for (int i = 0; i < 4; i++) {
		int* n = new int(i);
		std::thread t([n] { delete n; });
		t.join();
	}
	std::puts("ok");
	return 0;
}
